import * as React from "react";
import { cn } from "@/lib/utils";

export interface SelectOption {
  value: string;
  label: string;
  disabled?: boolean;
}

export interface SelectProps
  extends Omit<
    React.SelectHTMLAttributes<HTMLSelectElement>,
    "onChange" | "value" | "children"
  > {
  /** Optional label shown above the select. */
  label?: React.ReactNode;
  value: string;
  onChange: (value: string) => void;
  options: SelectOption[];
  placeholder?: string;
}

/**
 * Native `<select>` styled to match the design-system Input / Slider primitives.
 * Uses a small inline SVG caret instead of pulling in an icon library so the
 * design system stays icon-free (apps own that decision).
 */
const Select = React.forwardRef<HTMLSelectElement, SelectProps>(
  ({ label, value, onChange, options, placeholder, className, id: idProp, ...props }, ref) => {
    const autoId = React.useId();
    const id = idProp ?? (label !== undefined ? autoId : undefined);

    return (
      <div className="flex flex-col gap-2">
        {label !== undefined && (
          <label
            htmlFor={id}
            className="text-xs text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)]"
          >
            {label}
          </label>
        )}
        <div className="relative">
          <select
            ref={ref}
            id={id}
            value={value}
            onChange={e => onChange(e.target.value)}
            className={cn(
              "appearance-none w-full h-9 ps-3 pe-8 rounded-lg text-sm",
              "bg-[var(--color-surface-light)] dark:bg-[var(--color-surface-dark)]",
              "border border-[var(--color-border-light)] dark:border-[var(--color-border-dark)]",
              "text-[var(--color-text-primary-light)] dark:text-[var(--color-text-primary-dark)]",
              "hover:border-[var(--color-warm-300)] dark:hover:border-[var(--color-neutral-700)]",
              "focus-visible:outline-none focus-visible:ring-2",
              "focus-visible:ring-[var(--color-accent-500)] focus-visible:ring-offset-1",
              "disabled:cursor-not-allowed disabled:opacity-50",
              "transition-colors",
              className,
            )}
            {...props}
          >
            {placeholder && (
              <option value="" disabled>
                {placeholder}
              </option>
            )}
            {options.map(opt => (
              <option key={opt.value} value={opt.value} disabled={opt.disabled}>
                {opt.label}
              </option>
            ))}
          </select>
          {/* Caret -- logical end so it sits opposite the text in RTL too */}
          <svg
            className="absolute end-2.5 top-1/2 -translate-y-1/2 pointer-events-none w-3 h-3 text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)]"
            viewBox="0 0 12 12"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.75"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden
          >
            <path d="M2.5 4.5L6 8l3.5-3.5" />
          </svg>
        </div>
      </div>
    );
  },
);
Select.displayName = "Select";

export { Select };
